function resolveInteractiveSelection(replyId) {
  const id = String(replyId || '').trim();
  if (!id) return {};
  if (id.startsWith('brand__')) {
    const key = id.slice(7);
    const known = {
      jac: { brand_family: 'jac', autocom_group: 'jac_nonelectric', lead_type: 'particular' },
      jac_electricos: { brand_family: 'jac_electricos', autocom_group: 'jac_electrical', lead_type: 'particular' },
      jac_camiones: { brand_family: 'jac_camiones', autocom_group: 'jac_camiones', lead_type: 'comercial' },
      jetour: { brand_family: 'jetour', autocom_group: 'jetour', lead_type: 'particular' },
      karry: { brand_family: 'karry', autocom_group: 'karry', lead_type: 'comercial' },
    };
    return { top_brand: { key, ...(known[key] || {}) }, confidence: 0.99, source: 'interactive' };
  }
  if (id.startsWith('model__')) {
    const parts = id.split('__');
    if (parts.length >= 6) {
      return {
        top_model: {
          id: toNumberIfPossible(parts[1]),
          name: String(parts[4] || '').replace(/_/g, ' ').trim().toUpperCase(),
          autocom_group: parts[2] || null,
          lead_type: parts[3] || null,
          brand_family: parts[2] || null,
          action: parts[5] || null,
        },
        confidence: 0.99,
        source: 'interactive',
      };
    }
  }
  return {};
