function pickFirst(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim() !== '' && String(value).trim() !== '-') {
      return String(value).trim();
    }
  }
  return '';
}

function toNumberIfPossible(value) {
  if (value === undefined || value === null || value === '') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function titleCase(value) {
  return String(value || '').toLowerCase().replace(/\b\w/g, (m) => m.toUpperCase()).trim();
}

function normalizeSlug(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

function humanizeSlug(value) {
  return String(value || '').replace(/_/g, ' ').replace(/\s+/g, ' ').trim().toUpperCase();
}

function isLikelyGeneratedWidgetName(name) {
  const value = String(name || '').trim();
  if (!value) return true;
  if (/^[A-Za-z]+-[A-Za-z]+-\d{2,}$/i.test(value)) return true;
  if (/\d/.test(value) && /-/.test(value)) return true;
  if (/^(user|visitor|guest|anon|anonymous)[-_ ]?\d*$/i.test(value)) return true;
  return false;
}

function parseStructuredText(text) {
  const parsed = {};
  for (const line of String(text || '').split(/\r?\n/).map((l) => l.trim()).filter(Boolean)) {
    const match = line.match(/^([a-zA-Z0-9_ ]+):\s*(.+)$/);
    if (!match) continue;
    parsed[match[1].trim().toLowerCase().replace(/\s+/g, '_')] = match[2].trim();
  }
  return parsed;
}

