function uniqueStrings(values) {
  const seen = new Set();
  const out = [];
  for (const value of values || []) {
    const str = String(value || '').trim();
    if (!str) continue;
    const key = str.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(str);
  }
  return out;
}

function uniqueInts(values) {
  const seen = new Set();
  const out = [];
  for (const value of values || []) {
