const previousZone = pickFirst(canonicalLastSelectedEstablishment.zone, canonicalEstablishment.zone);
const previousLeadType = pickFirst(canonicalSelection.lead_type, canonicalLastSelectedModel.lead_type);
const previousAutocomGroup = pickFirst(canonicalSelection.autocom_group, canonicalLastSelectedModel.autocom_group);
const previousSearchMode = pickFirst(canonicalSelection.search_mode);
const previousCommercialSubtype = pickFirst(canonicalSelection.commercial_subtype);
const previousBrandFamily = pickFirst(canonicalSelection.brand_family, canonicalLastSelectedModel.brand_family);
const previousBookingPhase = pickFirst(canonicalContext.routing?.phase, canonicalJourney.phase);
const previousBookingIntent = pickFirst(canonicalContext.last_intention, canonicalJourney.intent);
const previousCandidateOptions = Array.isArray(canonicalEstablishment.candidate_options) ? canonicalEstablishment.candidate_options : [];
const previousZoneOptions = Array.isArray(canonicalEstablishment.zone_options) ? canonicalEstablishment.zone_options : [];

let selectedModel = previousModel || null;
let selectedModelId = previousModelId;
let selectedAutocomGroup = selection.autocom_group || previousAutocomGroup || null;
let selectedBrandFamily = selection.brand_family || previousBrandFamily || null;
let selectedLeadType = selection.lead_type || flow.lead_type || previousLeadType || null;
let commercialSubtype = selection.commercial_subtype || previousCommercialSubtype || null;
let searchMode = selection.search_mode || previousSearchMode || null;
let selectedModelChanged = false;

if (selection.kind === 'model_action') {
  selectedModelId = selection.selected_model_id;
  selectedModel = selection.selected_model;
  selectedAutocomGroup = selection.autocom_group || selectedAutocomGroup;
  selectedLeadType = selection.lead_type || selectedLeadType;
  selectedBrandFamily = selectedBrandFamily || normalizeSlug(selectedAutocomGroup);
  selectedModelChanged = true;
} else if (flow.selected_model) {
  selectedModel = String(flow.selected_model).trim().toUpperCase();
  selectedModelChanged = selectedModel.toLowerCase() !== String(previousModel || '').toLowerCase();
}

selectedLeadType = inferLeadTypeFromGroup(selectedAutocomGroup, selectedModel, selectedLeadType);

let selectedEstablishmentName = pickFirst(flow.selected_establishment_name, previousEstablishmentName);
let selectedEstablishmentId = toNumberIfPossible(flow.selected_establishment_id) ?? previousEstablishmentId;
let selectedZone = previousZone;
const normalizedSelection = normalized.trim();
const numericEstablishmentSelection = /^\d+$/.test(normalizedSelection) ? Number(normalizedSelection) : null;
if (interactiveReply.id && interactiveReply.id.startsWith('zone__')) {
  selectedZone = titleCase(interactiveReply.id.slice(6));
} else if (interactiveReply.id && interactiveReply.id.startsWith('est__')) {
  selectedEstablishmentId = toNumberIfPossible(interactiveReply.id.slice(5)) ?? previousEstablishmentId;
  const matchedById = previousCandidateOptions.find((candidate) => toNumberIfPossible(candidate?.id ?? candidate?.selected_establishment_id) === selectedEstablishmentId);
  if (matchedById) {
    selectedEstablishmentName = pickFirst(matchedById.name, matchedById.selected_establishment_name, selectedEstablishmentName);
    selectedZone = pickFirst(matchedById.zone, selectedZone);
  }
} else if (selectedEstablishmentId === null && numericEstablishmentSelection !== null && previousCandidateOptions.length >= numericEstablishmentSelection) {
  const selectedCandidate = previousCandidateOptions[numericEstablishmentSelection - 1] || null;
  if (selectedCandidate) {
    selectedEstablishmentName = pickFirst(selectedCandidate.name, selectedCandidate.selected_establishment_name, selectedEstablishmentName);
    selectedEstablishmentId = toNumberIfPossible(selectedCandidate.id ?? selectedCandidate.selected_establishment_id) ?? selectedEstablishmentId;
    selectedZone = pickFirst(selectedCandidate.zone, selectedZone);
  }
}

const resetsEstablishmentContext = ['search_mode', 'brand', 'lead_type', 'commercial_subtype', 'model_action'].includes(selection.kind);
if (resetsEstablishmentContext) {
  selectedEstablishmentName = null;
  selectedEstablishmentId = null;
  selectedZone = null;
}

const candidateName = pickFirst(flow.name, canonicalBasicContact.name, canonicalContactProfile.name, canonicalContactAttrs.name);
const validContactName = isLikelyGeneratedWidgetName(candidateName) ? '' : candidateName;
const webhookSender = $('Webhook').item.json.body?.sender || {};
const effectiveName = pickFirst(flow.name, canonicalBasicContact.name, canonicalContactProfile.name, canonicalContactAttrs.name, webhookSender.name, validContactName);
const effectiveEmail = pickFirst(flow.email, canonicalBasicContact.email, canonicalContactProfile.email, canonicalContactAttrs.email, webhookSender.email, webhookSender.custom_attributes?.email);
const effectiveIdentifier = pickFirst(flow.identifier, canonicalBasicContact.identifier, canonicalContactProfile.identifier, canonicalContactAttrs.identifier, webhookSender.identifier, webhookSender.custom_attributes?.identifier);
const effectivePhone = pickFirst(flow.phone_number, canonicalBasicContact.phone_number, canonicalContactProfile.phone_number, canonicalContactAttrs.phone_number, webhookSender.phone_number, $('Edit Fields').item.json.body?.conversation?.contact_inbox?.source_id);
const effectiveCity = pickFirst(flow.city, entityTopCity.city, inferredFreeTextCity, canonicalBasicContact.city, canonicalEstablishment.city, canonicalLastSelectedEstablishment.city, canonicalContactAttrs.city, webhookSender.custom_attributes?.city);
const selectedDate = pickFirst(flow.preferred_date, intentClassifier.selected_date, canonicalContext.schedule?.date, canonicalSchedule.date);
const selectedTime = pickFirst(flow.preferred_time, intentClassifier.selected_time, canonicalContext.schedule?.time, canonicalSchedule.time);
const purchaseTimeframeDays = mapEnrichmentTimeframe(flow.p2_tiempo_compra) ?? inferPurchaseDays(rawMessage, flow.purchase_timeframe_days);
const selectedLocationLat = parsedLocation?.lat ?? toNumberIfPossible(canonicalEstablishment.location?.lat);
const selectedLocationLng = parsedLocation?.lng ?? toNumberIfPossible(canonicalEstablishment.location?.lng);
const hasLocation = selectedLocationLat !== null && selectedLocationLng !== null;
const reviewedModels = uniqueStrings([...(canonicalSelectedModels.map((item) => item?.name).filter(Boolean)), selectedModel]);
const reviewedModelIds = uniqueInts([...(canonicalSelectedModels.map((item) => item?.id).filter((value) => value !== undefined && value !== null)), selectedModelId]);

const normalizedFlowIntent = String(flow.intent || '').toLowerCase();
const canonicalFlowIntent = !flow.is_flow_payload || !normalizedFlowIntent
  ? ''
  : (/agendar_prueba_manejo|conocer_vehiculos_en_persona|prueba_de_manejo|test_drive/.test(normalizedFlowIntent)
      ? 'schedule_phase4'
      : (/informacion_general|info_general|product_info/.test(normalizedFlowIntent)
          ? 'product_info'
          : normalizedFlowIntent));
const productInventoryQuery = /(catalogo|catálogo|vehiculos|veh[ií]culos|modelos|suvs|sedanes|camionetas|electricos|eléctricos|jetour|jac|karry|camiones)/i.test(normalized);
const wantsInPersonText = /(conocerlo en persona|conocer vehiculos en persona|verlo en persona|agendar|agenda|cita|prueba de manejo|test drive)/i.test(normalized);
const classifierLastIntention = String(intentClassifier.last_intention || '').trim();
const classifierAllowed = intentClassifier.allowed_by_business !== false;
const classifierConfidence = Number.isFinite(Number(intentClassifier.confidence)) ? Number(intentClassifier.confidence) : null;
const classifierNeedsBasicData = intentClassifier.needs_basic_data === true;
const classifierNeedsEnrichment = intentClassifier.needs_enrichment === true;
const classifierNeedsEstablishment = intentClassifier.needs_establishment === true;
const classifierNeedsScheduleFlow = intentClassifier.needs_schedule_flow === true;
const cityOnlyReply = Boolean(!flow.is_flow_payload && effectiveCity && normalizeSlug(latestMessageText) === normalizeSlug(effectiveCity));
const journeyNeedsEstablishment = Boolean(
  ['schedule_phase4', 'schedule_phase6'].includes(previousBookingIntent)
  || ['collect_establishment', 'collect_schedule', 'ready_to_book'].includes(previousBookingPhase)
);
const shouldPreserveScheduleIntent = Boolean(
  journeyNeedsEstablishment
  && !selectedEstablishmentId
  && Boolean(selectedModel || selectedModelId)
  && (cityOnlyReply || hasLocation || effectiveCity)
);
const enrichmentNeedsEstablishment = Boolean(
  flow.is_enrichment_payload
  && !selectedEstablishmentId
  && Boolean(selectedModel || selectedModelId)
  && (hasLocation || effectiveCity)
);

let intent = String(previousBookingIntent || 'fallback');
let confidence = 0.55;

if (selection.kind === 'model_action') {
  intent = selection.action === 'in_person' ? 'schedule_phase4' : 'product_info';
  confidence = 0.99;
} else if (flow.is_enrichment_payload) {
  intent = String(canonicalContext.last_intention || canonicalJourney.intent || 'schedule_phase4');
  confidence = 0.99;
} else if (flow.is_flow_payload && canonicalFlowIntent) {
  intent = canonicalFlowIntent;
  confidence = 0.98;
} else if (flow.is_phase6_payload) {
  intent = 'schedule_phase6';
  confidence = 0.98;
} else if (selection.route) {
  intent = String(canonicalContext.last_intention || canonicalJourney.intent || 'schedule_phase4');
  confidence = 0.95;
} else if (classifierAllowed && classifierLastIntention) {
  intent = classifierLastIntention;
  confidence = Math.max(confidence, classifierConfidence || 0.9);
} else if (wantsInPersonText) {
  intent = 'schedule_phase4';
  confidence = 0.88;
} else if (productInventoryQuery) {
  intent = 'product_info';
  confidence = 0.84;
}

if (shouldPreserveScheduleIntent && !['schedule_phase4', 'schedule_phase6'].includes(intent)) {
  intent = 'schedule_phase4';
  confidence = Math.max(confidence, 0.92);
}

if (enrichmentNeedsEstablishment && !['schedule_phase4', 'schedule_phase6'].includes(intent)) {
  intent = 'schedule_phase4';
  confidence = Math.max(confidence, 0.94);
}

const hasPersonalContactData = Boolean(effectiveName && effectiveEmail && effectiveIdentifier && effectivePhone);
const personalComplete = Boolean(hasPersonalContactData && effectiveCity);
const existingLeadEnrichment = canonicalContext.enrichment?.payload || canonicalEnrichment.payload || null;
const leadEnrichmentCompleted = Boolean(
  flow.is_enrichment_payload ||
  canonicalContext.enrichment?.status === 'completed' ||
  canonicalEnrichment.status === 'completed' ||
  (existingLeadEnrichment && typeof existingLeadEnrichment === 'object' && existingLeadEnrichment.p7_comentario)
);

const shortReply = normalizeSlug(latestMessageText);
const promptMemoryQuestion = pickFirst(canonicalPromptMemory.last_question_key);
if (!flow.is_flow_payload && ['si', 'no'].includes(shortReply) && promptMemoryQuestion) {
  if (promptMemoryQuestion === 'p3_test_drive') intent = 'schedule_phase4';
  if (promptMemoryQuestion === 'p6_cotizacion') intent = 'product_info';
}

const leadEnrichmentPayload = flow.is_enrichment_payload ? {
  lead_type: selectedLeadType,
