  p4_forma_pago: flow.p4_forma_pago || null,
  p4_entrada_valor: flow.p4_entrada_valor || null,
  p4_retoma_modelo: flow.p4_retoma_modelo || null,
  p4_retoma_kilometraje: flow.p4_retoma_kilometraje || null,
  p5_competencia: flow.p5_competencia || null,
  p5_competencia_detalle: flow.p5_competencia_detalle || '',
  p6_cotizacion: flow.p6_cotizacion || null,
  p7_comentario: flow.p7_comentario || null,
  completed_at: new Date().toISOString(),
} : null;

const isExplicitInPersonSelection = selection.kind === 'model_action' && selection.action === 'in_person';
const shouldSendPersonalFlow = isWhatsapp && intent === 'schedule_phase4' && !hasPersonalContactData && !flow.is_flow_payload && (classifierNeedsBasicData || !hasPersonalContactData);
const shouldSendSearchPrompt = isWhatsapp && ['schedule_phase4', 'product_info'].includes(intent) && hasPersonalContactData && !selectedModel && !classifierNeedsEstablishment && !classifierNeedsScheduleFlow;
const shouldSendEnrichmentFlow = isWhatsapp && !flow.is_flow_payload && hasPersonalContactData && Boolean(selectedModel || selectedModelId) && !leadEnrichmentCompleted && (isExplicitInPersonSelection || previousBookingPhase === 'collect_enrichment' || (classifierNeedsEnrichment && ['schedule_phase4', 'schedule_phase6'].includes(intent)));
const scheduleJourneyActive = ['schedule_phase4', 'schedule_phase6'].includes(intent) || shouldPreserveScheduleIntent || enrichmentNeedsEstablishment;
const shouldResolveEstablishment = Boolean((classifierNeedsEstablishment || scheduleJourneyActive) && leadEnrichmentCompleted && Boolean(selectedModel || selectedModelId) && !selectedEstablishmentId && (hasLocation || effectiveCity));
const shouldRequestLocation = Boolean(isWhatsapp && scheduleJourneyActive && leadEnrichmentCompleted && Boolean(selectedModel || selectedModelId) && !selectedEstablishmentId && !hasLocation && !effectiveCity);
const shouldSendPhase6Flow = Boolean(isWhatsapp && (classifierNeedsScheduleFlow || scheduleJourneyActive) && leadEnrichmentCompleted && Boolean(selectedModel || selectedModelId) && Boolean(selectedEstablishmentId) && !(selectedDate && selectedTime));
const readyToBook = Boolean(intent === 'schedule_phase6' && leadEnrichmentCompleted && personalComplete && Boolean(selectedModel || selectedModelId) && Boolean(selectedEstablishmentId) && selectedDate && selectedTime);

let discoveryRoute = null;
if (selection.route === 'send_brand_selector') discoveryRoute = 'send_brand_selector';
if (selection.route === 'send_type_selector') discoveryRoute = 'send_type_selector';
if (selection.route === 'send_commercial_selector') discoveryRoute = 'send_commercial_selector';

const wantsCarousel = selection.route === 'send_carousel' || (productInventoryQuery && !selectedModel && !selection.route && !flow.is_flow_payload);
const catalogBrandSelectionActive = selection.kind === 'brand';
const carouselFilters = {
  segment: 'all',
  autocom_group: catalogBrandSelectionActive ? (selection.autocom_group ?? '') : (selection.autocom_group || selectedAutocomGroup || ''),
  lead_type: catalogBrandSelectionActive ? (selection.lead_type ?? '') : (selection.lead_type || selectedLeadType || ''),
  brand_family: catalogBrandSelectionActive ? (selection.brand_family ?? '') : (selection.brand_family || selectedBrandFamily || ''),
  brand_key: selection.brand_key || '',
  catalog_limit: selection.brand_key === 'jac_motors' ? 20 : 10,
  base_only: true,
  query: selection.query || '',
};

const missingFields = [];
if (intent === 'schedule_phase4' || intent === 'schedule_phase6') {
  if (!effectiveName) missingFields.push('nombre');
  if (!effectiveEmail) missingFields.push('email');
  if (!effectiveIdentifier) missingFields.push('cedula');
  if (!effectivePhone) missingFields.push('telefono');
  if (!effectiveCity && !hasLocation) missingFields.push('ciudad');
  if (!(selectedModel || selectedModelId)) missingFields.push('modelo');
  if (leadEnrichmentCompleted && !(selectedEstablishmentName || selectedEstablishmentId)) missingFields.push('establecimiento');
  if (intent === 'schedule_phase6') {
    if (!selectedDate) missingFields.push('fecha');
    if (!selectedTime) missingFields.push('hora');
  }
}

return [{
  json: {
    ...$json,
    parsed_flow: flow,
    interactive_reply: interactiveReply,
    parsed_location: parsedLocation,
    intent_resolver: {
      intent,
      confidence,
      selected_model: selectedModel || null,
      selected_model_id: selectedModelId,
      selected_model_changed: selectedModelChanged,
      selected_establishment_name: selectedEstablishmentName || null,
