      },
      lead_type: selectedLeadType || null,
      autocom_group: selectedAutocomGroup || null,
      brand_family: selectedBrandFamily || null,
      commercial_subtype: commercialSubtype || null,
      search_mode: searchMode || null,
      lead_enrichment_completed: leadEnrichmentCompleted,
