const bestMatch = establishmentRes.best_match || {};
const canonical = base.canonical_context || {};
const updatePayload = base.conversation_update_payload || {};
const selectedEstablishmentName = base.selected_establishment_name_resolved || canonical.last_selected_establishment?.name || canonical.establishment?.selected_name || 'el concesionario seleccionado';
