function formatAppointmentSlot(slotStart) {
  if (!slotStart) return { date: '', time: '' };
  const parsed = new Date(slotStart);
  if (Number.isNaN(parsed.getTime())) return { date: '', time: '' };
  return {
    date: new Intl.DateTimeFormat('es-CO', {
      timeZone: 'America/Bogota',
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
    }).format(parsed),
    time: new Intl.DateTimeFormat('es-CO', {
      timeZone: 'America/Bogota',
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    }).format(parsed),
  };
}

const slotFallback = formatAppointmentSlot(appointment?.slot_start || appointment?.start_at);
const selectedDate = updatePayload.selected_date || base.selected_date || canonical.schedule?.date || slotFallback.date || '';
const selectedTime = updatePayload.selected_time || base.selected_time || canonical.schedule?.time || slotFallback.time || '';
const replyLines = [
  'Listo, tu prueba de manejo quedó registrada con éxito.',
