const canonicalContext = base.canonical_context || {};
const canonicalEstablishment = canonicalContext.establishment || {};
const city = data.selected_city || canonicalEstablishment.city || canonicalContext.basic_contact?.city || 'tu ciudad';
const previousRepeatCount = Number(canonicalEstablishment.prompt_repeat_count ?? 0) || 0;
const previousType = String(canonicalEstablishment.prompt_type || '');
