const original = $('Prepare Meta Action').item.json || {};
const out = { ...original };
const binary = $input.first()?.binary?.data;
const interactive = out.meta_payload?.interactive;
const params = interactive?.action?.parameters;
const flowData = params?.flow_action_payload?.data;

if (!interactive || !params || !flowData) {
  return [{ json: out }];
}

if (!binary?.data) {
  out.enrichment_image_error = 'missing_binary_data';
  return [{ json: out }];
}

out.meta_payload = {
  ...out.meta_payload,
  interactive: {
    ...interactive,
    action: {
      ...interactive.action,
      parameters: {
        ...params,
        flow_action_payload: {
          ...params.flow_action_payload,
          data: {
            ...flowData,
            model_image: binary.data,
          },
        },
      },
    },
  },
};
out.enrichment_image_meta = {
  mime_type: binary.mimeType || null,
  file_name: binary.fileName || null,
  file_size: binary.fileSize || null,
  base64_length: String(binary.data || '').length,
  source: 'http_request_binary'
};
return [{ json: out }];
